// STRUCTURAL directives add/remove elements. The * is sugar for <ng-template>.
<div *ngIf="show">Visible only if show is true</div>
<li *ngFor="let item of items">{{item}}</li>     // repeats <li> per item

// ATTRIBUTE directives change an existing element (no *).
<p [ngClass]="{ active: isActive, muted: !isActive }">Text</p>  // toggles classes
<p [ngStyle]="{ 'color': isError ? 'red' : 'black' }">Text</p>  // sets style

// CUSTOM attribute directive: highlight an element on hover.
@Directive({ selector: '[appHighlight]' })
export class HighlightDirective {
  @HostListener('mouseenter') onMouseEnter() { this.el.nativeElement.style.bg = 'yellow'; }
  constructor(private el: ElementRef) {}
}
//   Usage: <p appHighlight>Hover me</p>
